package com.opensocket.aievent.core.issuetracking.application.recovery;
import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.opensocket.aievent.core.issuetracking.core.ProviderCircuitBreakerPolicy;import com.opensocket.aievent.core.issuetracking.recovery.*;
@Service public class ProviderHealthService {private final ProjectionRecoveryRepository repo;private final ProviderCircuitBreakerPolicy policy=new ProviderCircuitBreakerPolicy();private final ProjectionRecoveryEventLedger ledger;public ProviderHealthService(ProjectionRecoveryRepository repo,ProjectionRecoveryEventLedger ledger){this.repo=repo;this.ledger=ledger;}@Transactional public ProviderHealthState record(String tenant,String connection,String mapping,boolean success,boolean rateLimited,String failureCode,int queueDepth,int maxDepth,String actor,String correlation){var current=repo.findHealth(req(tenant),req(connection),blank(mapping)).orElseGet(()->fresh(tenant,connection,mapping,maxDepth,correlation));int failures=success?0:current.consecutiveFailures()+1;var status=policy.next(current.status(),failures,queueDepth,Math.max(1,maxDepth),rateLimited,success);OffsetDateTime now=OffsetDateTime.now(ZoneOffset.UTC);var next=new ProviderHealthState(current.tenantId(),current.healthId(),current.connectionId(),current.projectMappingId(),status,failures,current.successCount()+(success?1:0),current.failureCount()+(success?0:1),Math.max(0,queueDepth),Math.max(1,maxDepth),status==ProviderHealthStatus.OPEN_CIRCUIT?(current.openedAt()==null?now:current.openedAt()):null,status==ProviderHealthStatus.OPEN_CIRCUIT||status==ProviderHealthStatus.THROTTLED?now.plusSeconds(60):null,blank(failureCode),current.version()+1,current.createdAt(),now,correlation);if(current.version()==1&&repo.findHealth(tenant,connection,blank(mapping)).isEmpty())repo.saveHealth(next);else if(!repo.saveHealthExpectedVersion(next,current.version()))throw new IllegalStateException("PROVIDER_HEALTH_VERSION_CONFLICT");if(status!=current.status())ledger.append(tenant,"PROVIDER_HEALTH",current.healthId(),status==ProviderHealthStatus.OPEN_CIRCUIT?ProjectionRecoveryEventType.CIRCUIT_OPENED:status==ProviderHealthStatus.RECOVERING?ProjectionRecoveryEventType.CIRCUIT_RECOVERING:ProjectionRecoveryEventType.CIRCUIT_CLOSED,actor,status.name(),"{}",correlation);return next;}public List<ProviderHealthState> list(String tenant,ProviderHealthStatus status,int limit){return repo.listHealth(req(tenant),status,Math.max(1,Math.min(limit,1000)));}private ProviderHealthState fresh(String t,String c,String m,int d,String corr){OffsetDateTime n=OffsetDateTime.now(ZoneOffset.UTC);return new ProviderHealthState(t,"ph-"+UUID.randomUUID(),c,blank(m),ProviderHealthStatus.HEALTHY,0,0,0,0,Math.max(1,d),null,null,"",1,n,n,corr);}private String req(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value missing.");return v.trim();}private String blank(String v){return v==null?"":v.trim();}}
